# ---------------------------------------------------------------- custom textures (cars)
def paint(color, w, h, seed):
    r = np.random.default_rng(seed)
    base = np.array(color, float)
    y = np.linspace(1.08, 0.82, h)[:, None, None]          # lighter at the top, like sky reflection
    img = base * y + r.normal(0, 3, (h, w, 1))
    dirt = r.random((h, w)) < 0.015
    img[dirt] *= 0.75
    return np.clip(img, 0, 255)


def car_side(color, seed):
    w, h = 256, 64
    img = paint(color, w, h, seed)
    img[h // 2 - 1: h // 2 + 1] *= 0.7                      # body crease
    for x in (92, 150, 200):                                 # door seams
        img[6:h - 6, x: x + 2] *= 0.45
    for x in (130, 186):                                     # handles
        img[22:26, x: x + 12] = (40, 40, 40)
    for cx in (52, 204):                                     # wheel arches (dark)
        for yy in range(h):
            for xx in range(cx - 34, cx + 35):
                if (xx - cx) ** 2 + (yy - h - 6) ** 2 < 36 ** 2:
                    img[yy, xx] = (18, 18, 18)
    img[h - 4:] *= 0.5
    return img


def car_front(seed):
    w, h = 128, 32
    img = np.zeros((h, w, 3)) + (35, 35, 38)
    for yy in range(8, 24, 4):
        img[yy: yy + 2, 36: 92] = (80, 80, 84)               # grille bars
    for x0 in (6, 98):
        img[8:22, x0: x0 + 24] = (235, 232, 205)             # headlights
        img[10:20, x0 + 2: x0 + 22] = (255, 252, 230)
    img[26:] = (60, 60, 64)                                  # bumper
    return img


def car_back(seed):
    w, h = 128, 32
    img = np.zeros((h, w, 3)) + (40, 40, 44)
    for x0 in (6, 98):
        img[8:20, x0: x0 + 24] = (170, 20, 20)               # tail lights
        img[10:18, x0 + 2: x0 + 22] = (220, 40, 30)
    img[10:20, 48:80] = (210, 210, 200)                      # plate
    img[13:17, 52:76] = (40, 40, 60)
    img[26:] = (60, 60, 64)
    return img


def car_window(seed):
    w = h = 64
    img = np.zeros((h, w, 3)) + (38, 48, 58)
    yy, xx = np.mgrid[0:h, 0:w]
    streak = np.abs((xx + yy) - 40) < 7
    img[streak] = (90, 105, 120)
    img += nrng.normal(0, 2, img.shape)
    return np.clip(img, 0, 255)


