def charred(img, seed):
    """the same texture after the car burned out: soot-black, paint gone grey, rust coming through"""
    r = np.random.default_rng(seed)
    h, w = img.shape[:2]
    def smooth(cell):
        small = (r.random((max(h // cell, 2), max(w // cell, 2))) * 255).astype(np.uint8)
        return np.array(Image.fromarray(small).resize((w, h), Image.BILINEAR), float)[:, :, None] / 255.0
    luma = img.mean(axis=2, keepdims=True)
    out = img * 0.25 + luma * 0.75
    out = out * (0.10 + 0.22 * smooth(6)) + r.normal(0, 4, (h, w, 1))
    rust = np.clip((smooth(4) - 0.55) * 3.0, 0, 1) * np.clip(r.random((h, w, 1)) * 1.5, 0, 1)
    out = out * (1 - rust * 0.7) + np.array((96, 50, 24)) * rust * 0.7
    return np.clip(out, 0, 255)


