def water_texture(src, fog, density):
    """a copy of a Half-Life water texture with its own underwater fog: the engine takes the fog's colour from
    palette entry 3 and its density from entry 4's red (img_wad.c); pixels that used those entries move to the
    nearest other colour"""
    w, path, fo = wadtex.index()[src.upper()]
    d = open(path, 'rb').read()
    wd, hg, o0, o1, o2, o3 = struct.unpack_from('<II4I', d, fo + 16)
    idx = np.frombuffer(d[fo + o0: fo + o0 + wd * hg], np.uint8).reshape(hg, wd).copy()
    palo = fo + o3 + (wd // 8) * (hg // 8) + 2
    pal = np.frombuffer(d[palo: palo + 768], np.uint8).reshape(256, 3).astype(int)
    for k in (3, 4):
        dist = ((pal - pal[k]) ** 2).sum(1)
        dist[[3, 4]] = 1 << 30
        idx[idx == k] = int(dist.argmin())
    pal = pal.copy()
    pal[3], pal[4] = fog, (density, 0, 0)
    im = Image.fromarray(idx, 'P')
    im.putpalette(pal.astype(np.uint8).flatten().tolist())
    return im


