# ---------------------------------------------------------------- terrain
def smoothstep(a, b, x):
    t = min(max((x - a) / (b - a), 0.0), 1.0)
    return t * t * (3 - 2 * t)


def vnoise(x, y, scale, seed):
    """cheap smooth 2D value noise in [-1, 1]"""
    x, y = x / scale, y / scale
    xi, yi = math.floor(x), math.floor(y)
    def h(i, j):
        return random.Random((i * 73856093) ^ (j * 19349663) ^ seed).uniform(-1, 1)
    fx, fy = x - xi, y - yi
    fx, fy = fx * fx * (3 - 2 * fx), fy * fy * (3 - 2 * fy)
    a = h(xi, yi) + (h(xi + 1, yi) - h(xi, yi)) * fx
    b = h(xi, yi + 1) + (h(xi + 1, yi + 1) - h(xi, yi + 1)) * fx
    return a + (b - a) * fy


FLAT = [(-1400, -900, 700, 1024), (700, -1000, 1450, -128)]   # the town, the gas station's lot


def flat_dist(x, y):
    """distance outside the flat zone (the road strip plus the town rectangles)"""
    d = abs(y) - 320
    for x0, y0, x1, y1 in FLAT:
        dx = max(x0 - x, 0, x - x1)
        dy = max(y0 - y, 0, y - y1)
        d = min(d, math.hypot(dx, dy) if (dx or dy) else -1)
    return max(d, 0)


def height(x, y):
    d = flat_dist(x, y)
    hill = smoothstep(0, 900, d) * (170 + 110 * vnoise(x, y, 700, 1) + 45 * vnoise(x, y, 260, 2))
    edge = max(abs(x), abs(y)) - 1450
    mountain = (max(edge, 0) / 600.0) ** 2 * 420
    return int(round((hill + mountain) / 8.0)) * 8


G = 256
N = 2 * H // G
grid = [[height(-H + i * G, -H + j * G) for j in range(N + 1)] for i in range(N + 1)]


def surface_z(x, y):
    """height of the triangulated ground at (x, y), same triangle split as the brushes below"""
    i = min(max(int((x + H) // G), 0), N - 1)
    j = min(max(int((y + H) // G), 0), N - 1)
    fx, fy = (x + H - i * G) / G, (y + H - j * G) / G
    z00, z10, z11, z01 = grid[i][j], grid[i + 1][j], grid[i + 1][j + 1], grid[i][j + 1]
    if (i + j) % 2 == 0:
        if fx >= fy:
            return z00 + fx * (z10 - z00) + fy * (z11 - z10)
        return z00 + fy * (z01 - z00) + fx * (z11 - z01)
    if fx + fy <= 1:
        return z00 + fx * (z10 - z00) + fy * (z01 - z00)
    return z11 + (1 - fx) * (z01 - z11) + (1 - fy) * (z10 - z11)


def pond_depth(x, y):
    """how far the pond's hollow sinks below the ground at (x, y): a bowl with a ragged shore, deeper to the north"""
    px, py, rx, ry, _ = POND
    r = math.hypot((x - px) / rx, (y - py) / ry) * (1 + 0.12 * vnoise(x, y, 140, 21))
    return (88 + 24 * smoothstep(py - ry, py + ry, y)) * smoothstep(1.0, 0.3, r)


def ground_z(x, y):
    """the ground's height, with the pond's hollow"""
    ax0, ay0, ax1, ay1 = POND_AREA
    return surface_z(x, y) - (pond_depth(x, y) if ax0 <= x <= ax1 and ay0 <= y <= ay1 else 0)


