        corners = [(x0, y0, grid[i][j]), (x0 + G, y0, grid[i + 1][j]), (x0 + G, y0 + G, grid[i + 1][j + 1]), (x0, y0 + G, grid[i][j + 1])]
        tris = [(0, 1, 2), (0, 2, 3)] if (i + j) % 2 == 0 else [(0, 1, 3), (1, 2, 3)]
