def pond_lines(a0, a1, c, r):
    w0, w1 = int(c - 1.2 * r) // 32 * 32, int(c + 1.2 * r) // 32 * 32 + 32
    return sorted(set(range(a0, a1 + 1, 64)) | {a for a in range(w0, w1 + 1, 32) if a0 <= a <= a1})
