# ---------------------------------------------------------------- buildings
def wall(axis, fixed0, fixed1, a0, a1, h, openings, tex_out, tex_in, out_side):
    """Wall along `axis` ('x' or 'y') between a0..a1, thickness fixed0..fixed1, height 0..h (on an 8-unit floor),
    minus openings [(o0, o1, z0, z1)]. out_side: '+' or '-' (which thickness side faces outdoors)."""
    cuts = sorted({a0, a1} | {o[0] for o in openings} | {o[1] for o in openings})
    out = []
    other = 'y' if axis == 'x' else 'x'
    tex = {'all': tex_in, other + out_side: tex_out, 'top': tex_out}
    for s0, s1 in zip(cuts, cuts[1:]):
        holes = sorted((o[2], o[3]) for o in openings if o[0] <= s0 and o[1] >= s1)
        z = 8
        for z0, z1 in holes + [(h, h)]:
            if z0 > z:
                if axis == 'x':
                    out.append(box((s0, fixed0, z), (s1, fixed1, z0), tex))
                else:
                    out.append(box((fixed0, s0, z), (fixed1, s1, z0), tex))
            z = max(z, z1)
    return out


def glass(axis, fixed0, fixed1, o):
    if axis == 'x':
        b = box((o[0], fixed0 + 6, o[2]), (o[1], fixed1 - 6, o[3]), 'GLASS_DARK')
    else:
        b = box((fixed0 + 6, o[0], o[2]), (fixed1 - 6, o[1], o[3]), 'GLASS_DARK')
    return entity({'classname': 'func_breakable', 'material': '0', 'health': '20', 'rendermode': '2', 'renderamt': '110'}, [b])


def prop(model, x, y, yaw=None, solid=True, z=None):
    zz = surface_z(x, y) if z is None else z
    ents.append(entity({'classname': 'sc_prop', 'model': model, 'origin': '%d %d %d' % (x, y, zz),
                        'angles': '0 %d 0' % (rng.randint(0, 359) if yaw is None else yaw), 'solid': '2' if solid else '0'}))


