def fit(u, v, origin_u, origin_v, size_u, size_v, tw, th):
    """face texinfo: texture of tw x th pixels stretched over size_u x size_v units starting at (origin_u, origin_v)"""
    su, sv = size_u / tw, size_v / th
    return {'u': u, 'v': v, 'shift': (-origin_u / su, origin_v / sv), 'scale': (su, sv)}


def dbox(mn, mx, tex, mat, cut=None, **kw):
    """a diggable box: it gives `mat` when dug, and shows `cut` (default: its side texture) where it is cut open"""
    b = box(mn, mx, tex, **kw)
    if cut is None:
        cut = tex if isinstance(tex, str) else (tex.get('side') or tex.get('all') or next(iter(tex.values())))
    dyn.append((b, mat, cut))
    return b


def side_box(side, face, a0, a1, z0, z1, depth, tex, mat):
    """a box against a building's outer face on `side` ('x-', 'x+', 'y-', 'y+'), from a0 to a1 along it"""
    if side == 'y-':
        return dbox((a0, face - depth, z0), (a1, face, z1), tex, mat)
    if side == 'y+':
        return dbox((a0, face, z0), (a1, face + depth, z1), tex, mat)
    if side == 'x-':
        return dbox((face - depth, a0, z0), (face, a1, z1), tex, mat)
    return dbox((face, a0, z0), (face + depth, a1, z1), tex, mat)


def door(side, wall0, wall1, a, z0=8, z1=120, tex='DOOR_02'):
    """a Half-Life door (func_door_rotating, opens away from whoever pushes it) in the doorway centred at `a`"""
    c = (wall0 + wall1) / 2
    tw, th = wadtex.load(tex)[0].size     # the whole door texture on the panel
    if side in ('y-', 'y+'):
        f = fit((1, 0, 0), (0, 0, -1), a - 30, z1, 60, z1 - z0, tw, th)
        panel = box((a - 30, c - 2, z0), (a + 30, c + 2, z1), {'all': 'DOOR_MTL_01', 'y+': tex, 'y-': tex}, **{'y+': f, 'y-': f})
        origin = box((a - 32, c - 2, z0), (a - 28, c + 2, z1), 'ORIGIN')
    else:
        f = fit((0, 1, 0), (0, 0, -1), a - 30, z1, 60, z1 - z0, tw, th)
        panel = box((c - 2, a - 30, z0), (c + 2, a + 30, z1), {'all': 'DOOR_MTL_01', 'x+': tex, 'x-': tex}, **{'x+': f, 'x-': f})
        origin = box((c - 2, a - 32, z0), (c + 2, a - 28, z1), 'ORIGIN')
    ents.append(entity({'classname': 'func_door_rotating', 'speed': '140', 'distance': '90', 'wait': '5', 'movesnd': '1',
                        'stopsnd': '1', 'angles': '0 0 0', 'spawnflags': '0'}, [panel, origin]))


def crate(x, y, z, size=48, pushable=False):
    """Half-Life's wooden crate: shoot or smash it to pieces (func_breakable, wood); a pushable one slides when walked
    into (func_pushable, breakable too)"""
    f = {k: fit(u, (0, 0, -1), o, z + size, size, size, 64, 64) for k, u, o in
         (('x+', (0, 1, 0), y - size / 2), ('x-', (0, 1, 0), y - size / 2), ('y+', (1, 0, 0), x - size / 2), ('y-', (1, 0, 0), x - size / 2))}
    f['top'] = fit((1, 0, 0), (0, -1, 0), x - size / 2, -(y - size / 2), size, size, 64, 64)
    b = box((x - size / 2, y - size / 2, z), (x + size / 2, y + size / 2, z + size), 'CRATE02', **f)
    if pushable:
        ents.append(entity({'classname': 'func_pushable', 'spawnflags': '128', 'material': '1', 'health': '30', 'friction': '50', 'size': '2'}, [b]))
    else:
        ents.append(entity({'classname': 'func_breakable', 'material': '1', 'health': '30', 'spawnobject': '0'}, [b]))
    FURNITURE.append((x - size / 2, y - size / 2, x + size / 2, y + size / 2))


def desk(cx, cy, facing, z=8):
    """Half-Life's office desk: a wooden top on a drawer pedestal and a panel leg; `facing` = where the sitter
    is ('y-', 'y+', 'x-', 'x+')"""
    L, W, H = 64, 32, 30
    along_x = facing in ('y-', 'y+')
    x0, x1, y0, y1 = (cx - L / 2, cx + L / 2, cy - W / 2, cy + W / 2) if along_x else (cx - W / 2, cx + W / 2, cy - L / 2, cy + L / 2)
    dbox((x0, y0, z + H - 2), (x1, y1, z + H), {'top': 'M_WOOD1', 'all': 'DESK_GEN'}, B_PLANKS)
    if along_x:
        f = fit((1, 0, 0), (0, 0, -1), x1 - 18, z + H - 2, 16, H - 2, 64, 64)
        dbox((x1 - 18, y0 + 2, z), (x1 - 2, y1 - 2, z + H - 2), {'all': 'DESK_GEN', facing: 'DESK_DRAWER1'}, B_PLANKS, **{facing: f})
        dbox((x0 + 2, y0 + 2, z), (x0 + 4, y1 - 2, z + H - 2), 'DESK_GEN', B_PLANKS)
    else:
        f = fit((0, 1, 0), (0, 0, -1), y1 - 18, z + H - 2, 16, H - 2, 64, 64)
        dbox((x0 + 2, y1 - 18, z), (x1 - 2, y1 - 2, z + H - 2), {'all': 'DESK_GEN', facing: 'DESK_DRAWER1'}, B_PLANKS, **{facing: f})
        dbox((x0 + 2, y0 + 2, z), (x1 - 2, y0 + 4, z + H - 2), 'DESK_GEN', B_PLANKS)
    FURNITURE.append((x0, y0, x1, y1))
    # and a chair for it
    off = {'y-': (0, -30, 90), 'y+': (0, 30, 270), 'x-': (-30, 0, 0), 'x+': (30, 0, 180)}[facing]
    prop('models/ginsmodels/gins_deskchair.mdl', cx + off[0], cy + off[1], yaw=off[2], z=z + 32)


def shelf(x0, y0, x1, y1, z=8, h=100, tex='BA_STEEL_01', mat=B_METAL):
    """a storage rack: two end frames and four boards (metal unless told otherwise)"""
    along_x = x1 - x0 > y1 - y0
    if along_x:
        dbox((x0, y0, z), (x0 + 2, y1, z + h), tex, mat)
        dbox((x1 - 2, y0, z), (x1, y1, z + h), tex, mat)
    else:
        dbox((x0, y0, z), (x1, y0 + 2, z + h), tex, mat)
        dbox((x0, y1 - 2, z), (x1, y1, z + h), tex, mat)
    for k in range(4):
        zz = z + 4 + k * (h - 8) / 3
        if along_x:
            dbox((x0 + 2, y0, zz), (x1 - 2, y1, zz + 2), tex, mat)
        else:
            dbox((x0, y0 + 2, zz), (x1, y1 - 2, zz + 2), tex, mat)
    FURNITURE.append((x0, y0, x1, y1))


def counter(x0, y0, x1, y1, z=8, h=40):
    dbox((x0, y0, z + h - 3), (x1, y1, z + h), {'top': 'M_WOOD1', 'all': 'WOOD_PANEL_01'}, B_PLANKS)
    dbox((x0 + 2, y0 + 2, z), (x1 - 2, y1 - 2, z + h - 3), 'WOOD_PANEL_01', B_PLANKS)
    FURNITURE.append((x0, y0, x1, y1))


# what each kind of building is like inside
KINDS = {
    'office':    {'floor': 'CARPET_TAN', 'ceil': 'CEILING_TILE', 'wall_in': 'WALL_PLASTER'},
    'shop':      {'floor': 'C1A1_LINO', 'ceil': 'CEILING_TILE', 'wall_in': 'WALL_PLASTER'},
    'warehouse': {'floor': 'CONCRETETILE', 'ceil': 'OUT_CONCRETE1', 'wall_in': 'conc_wall_01'},
    'house':     {'floor': 'EASTWOOD01', 'ceil': 'FIFTIES_CEIL01', 'wall_in': 'WALL_PLASTER'},
}
H1 = 128    # the upper floor of a two-storey building


def building(x0, y0, x1, y1, h, tex_out, kind, door_side, windows=2, roof='OUT_ROOF2', light=(255, 236, 200, 160),
             floors=1, gable=0, door_tex='DOOR_02', door_offset=0):
    """A Half-Life-style building, all of it diggable (each part gives its own material): framed windows with
    glass, a door in a steel frame, the kind's floor, ceiling and walls, upper floors (up to three storeys) up
    switchback stairs along the back wall, a flat roof with a parapet and an air conditioner, or a gable roof
    `gable` units high. Buildings with upper floors have their door on y- or y+ (the stairs climb the far wall)."""
    T = 16
    K = KINDS[kind]
    BUILDINGS.append((x0, y0, x1, y1))
    mat = MATERIAL.get(tex_out, B_CONCRETE)
    roof_mat = B_ASPHALT if roof in ('DOUBLE_ASPHALT', 'OUT_ROOF2') else mat
    dbox((x0, y0, 0), (x1, y1, 8), {'top': K['floor'], 'side': tex_out}, mat, cut='OUT_CONCRETE1')     # floor slab
    if gable:
        dbox((x0, y0, h), (x1, y1, h + 8), {'top': 'OUT_CONCRETE1', 'bottom': K['ceil'], 'side': tex_out}, mat)
        # two sloping halves, the ridge along the longer side, eaves 12 out with a 6-unit fascia
        if x1 - x0 >= y1 - y0:
            ym = (y0 + y1) / 2
            for ya, yb, za, zb in ((y0 - 12, ym, h + 14, h + 8 + gable), (ym, y1 + 12, h + 8 + gable, h + 14)):
                dyn.append((prism([(x0 - 12, ya), (x1 + 12, ya), (x1 + 12, yb), (x0 - 12, yb)], h + 8, [za, za, zb, zb], roof, tex_out, 'WOOD_PANEL_01'),
                            roof_mat, tex_out))
        else:
            xm = (x0 + x1) / 2
            for xa, xb, za, zb in ((x0 - 12, xm, h + 14, h + 8 + gable), (xm, x1 + 12, h + 8 + gable, h + 14)):
                dyn.append((prism([(xa, y0 - 12), (xb, y0 - 12), (xb, y1 + 12), (xa, y1 + 12)], h + 8, [za, zb, zb, za], roof, tex_out, 'WOOD_PANEL_01'),
                            roof_mat, tex_out))
    else:
        dbox((x0, y0, h), (x1, y1, h + 16), {'top': roof, 'bottom': K['ceil'], 'side': tex_out}, roof_mat)
        # parapet, and the roof's machinery
        for a in ((x0, y0, x1, y0 + 8), (x0, y1 - 8, x1, y1), (x0, y0 + 8, x0 + 8, y1 - 8), (x1 - 8, y0 + 8, x1, y1 - 8)):
            dbox((a[0], a[1], h + 16), (a[2], a[3], h + 40), {'top': 'OUT_CONCRETE1', 'side': tex_out}, mat)
        ax, ay = x0 + (x1 - x0) * 0.62, y0 + (y1 - y0) * 0.4
        dbox((ax - 32, ay - 24, h + 16), (ax + 32, ay + 24, h + 56), {'top': 'BA_STEEL_01', 'side': 'PRXVENT1'}, B_METAL)
        # the unit breathes out a little warm air (sc_emitter, game/dlls/svencraft/sc_emitter.cpp)
        ents.append(entity({'classname': 'sc_emitter', 'origin': '%d %d %d' % (ax, ay, h + 60), 'kind': '0', 'rate': '3', 'renderamt': '45', 'scale': '0.4'}))
        dbox((ax - 70, ay + 30, h + 16), (ax - 58, ay + 42, h + 52), 'BA_STEEL_01', B_METAL)

    if floors == 3:
        rows = [(48, 104), (168, 224), (288, 344)]
    elif floors == 2:
        rows = [(56, 112), (160, 208)]
    else:
        rows = [(64, 128)] + ([(160, 208)] if h > 200 else [])

    def win_list(a0, a1, door_at):
        ops = []
        for k in range(windows):
            c = a0 + (a1 - a0) * (k + 1) / (windows + 1)
            if door_at is not None and abs(c - door_at) < 96:
                continue
            c = int(c // 8 * 8)
            ops += [(c - 32, c + 32) + r for r in rows]
        if door_at is not None:
            ops.append((door_at - 32, door_at + 32, 8, 120))
        return ops

    mid_x, mid_y = int((x0 + x1) // 2 // 8 * 8) + door_offset, int((y0 + y1) // 2 // 8 * 8) + door_offset
    DOORS.append({'y-': (mid_x, y0, 0, -1), 'y+': (mid_x, y1, 0, 1), 'x-': (x0, mid_y, -1, 0), 'x+': (x1, mid_y, 1, 0)}[door_side])
    sides = {
        'y-': ('x', y0, y0 + T, x0, x1, '-', mid_x if door_side == 'y-' else None, y0),
        'y+': ('x', y1 - T, y1, x0, x1, '+', mid_x if door_side == 'y+' else None, y1),
        'x-': ('y', x0, x0 + T, y0 + T, y1 - T, '-', mid_y if door_side == 'x-' else None, x0),
        'x+': ('y', x1 - T, x1, y0 + T, y1 - T, '+', mid_y if door_side == 'x+' else None, x1),
    }
    for key, (axis, f0, f1, a0, a1, outs, door_at, face) in sides.items():
        ops = win_list(a0, a1, door_at)
        for b in wall(axis, f0, f1, a0, a1, h, ops, tex_out, K['wall_in'], outs):
            dyn.append((b, mat, tex_out))
        for o in ops:
            if o[2] > 8:
                ents.append(glass(axis, f0, f1, o))
                # a concrete sill under it and a lintel over it
                side_box(key, face, o[0] - 6, o[1] + 6, o[2] - 6, o[2], 6, 'OUT_CONCRETE1', B_CONCRETE)
                side_box(key, face, o[0] - 4, o[1] + 4, o[3], o[3] + 8, 2, 'OUT_CONCRETE1', B_CONCRETE)
            else:
                # the doorway: a steel frame, a step up to the floor, the door
                side_box(key, face, o[0] - 6, o[0], o[2], o[3] + 6, 2, 'BA_STEEL_01', B_METAL)
                side_box(key, face, o[1], o[1] + 6, o[2], o[3] + 6, 2, 'BA_STEEL_01', B_METAL)
                side_box(key, face, o[0], o[1], o[3], o[3] + 6, 2, 'BA_STEEL_01', B_METAL)
                side_box(key, face, o[0] - 16, o[1] + 16, 0, 6, 24, {'top': 'OUT_CONCRETE1', 'side': 'IN_CURB1'}, B_CONCRETE)
                door(key, f0, f1, (o[0] + o[1]) / 2, tex=door_tex)
                # a lamp over the door
                lx, ly = {'y-': (door_at, face - 14), 'y+': (door_at, face + 14), 'x-': (face - 14, door_at), 'x+': (face + 14, door_at)}[key]
                side_box(key, face, door_at - 10, door_at + 10, 140, 148, 12, {'all': 'BA_STEEL_01', 'bottom': 'streetlight1'}, B_METAL)
                ents.append(entity({'classname': 'light', 'origin': '%d %d 134' % (lx, ly), '_light': '255 214 150 70'}))

    # upper floors: slabs every 120 units with a stairwell over the flight that comes up through them. The
    # flights switch back along the back wall: the first rises +x in the strip against it, the next -x in front
    ix0, iy0, ix1, iy1 = x0 + T, y0 + T, x1 - T, y1 - T
    sx0, sx1 = ix0 + 24, ix0 + 24 + 160
    for f in range(1, floors):
        z = 8 + 120 * f
        if door_side == 'y+':                               # this flight's strip, f = 1 against the far wall
            strip = ( iy0 + 64 * ( f - 1 ), iy0 + 64 * f )
            hx0, hy0, hx1, hy1 = sx0 - 8, strip[0], sx1 + 8, strip[1] + 8
        else:
            strip = ( iy1 - 64 * f, iy1 - 64 * ( f - 1 ))
            hx0, hy0, hx1, hy1 = sx0 - 8, strip[0] - 8, sx1 + 8, strip[1]
        for a, b in (((ix0, iy0), (ix1, hy0)), ((ix0, hy0), (hx0, hy1)), ((hx1, hy0), (ix1, hy1)), ((ix0, hy1), (ix1, iy1))):
            if b[0] - a[0] >= 1 and b[1] - a[1] >= 1:
                dbox((a[0], a[1], z - 8), (b[0], b[1], z), {'top': K['floor'], 'bottom': K['ceil'], 'side': K['wall_in']}, mat,
                     cut='OUT_CONCRETE1')
        base = z - 120
        for k in range(8):
            xa, xb = ( sx0 + k * 20, sx0 + ( k + 1 ) * 20 ) if f % 2 else ( sx1 - ( k + 1 ) * 20, sx1 - k * 20 )
            dbox((xa, strip[0], base), (xb, strip[1], base + 15 * ( k + 1 )), {'top': '4_STEPS01', 'side': K['wall_in']}, mat,
                 cut='OUT_CONCRETE1')
        FURNITURE.append((sx0, strip[0], sx1, strip[1]))
        ents.append(entity({'classname': 'light', 'origin': '%d %d %d' % ((x0 + x1) // 2, (y0 + y1) // 2, z - 20),
                            '_light': '%d %d %d %d' % light}))
    ents.append(entity({'classname': 'light', 'origin': '%d %d %d' % ((x0 + x1) // 2, (y0 + y1) // 2, h - 24),
                        '_light': '%d %d %d %d' % light}))
    return ix0, iy0, ix1, iy1


