# ---------------------------------------------------------------- cars (brush-built, like classic HL maps)
def extrude_y(poly_xz, y0, y1, cap, sides):
    b = Brush()
    b.face([(x, y1, z) for x, z in poly_xz], cap)
    b.face([(x, y0, z) for x, z in reversed(poly_xz)], cap)
    for i in range(len(poly_xz)):
        (xa, za), (xb, zb) = poly_xz[i], poly_xz[(i + 1) % len(poly_xz)]
        b.face([(xa, y0, za), (xb, y0, zb), (xb, y1, zb), (xa, y1, za)], sides[i] if isinstance(sides, list) else sides)
    return b


def car(cx, cy, along_y, color, wrecked=False, z=2, lightbar=False):
    CARS.append((cx, cy, along_y))
    """a sedan, 184 long; along_y turns it 90 degrees; z = ground height under it."""
    paintt, sidet = 'car_' + color, 'carside_' + color
    def P(x, y, zz):
        return (cx - y, cy + x, zz + z) if along_y else (cx + x, cy + y, zz + z)
    brushes = []
    def add(b):
        for f in b.faces:
            f[0] = [P(*v) for v in f[0]]
        brushes.append(b)
    L = 88
    # body: sides carry the door texture, front the grille, back the tail lights
    lu = (0, 1, 0) if along_y else (1, 0, 0)
    side_fit = fit(lu, (0, 0, -1), (cy if along_y else cx) - L, 34 + z, 2 * L, 22, 256, 64)
    wu = (1, 0, 0) if along_y else (0, 1, 0)
    end_fit = fit(wu, (0, 0, -1), (cx if along_y else cy) - 36, 34 + z, 72, 22, 128, 32)
    body = box((-L, -36, 12), (L, 36, 34), {'top': paintt, 'bottom': 'car_under', 'x+': 'car_front', 'x-': 'car_back', 'y+': sidet, 'y-': sidet},
               **{'y+': side_fit, 'y-': side_fit, 'x+': end_fit, 'x-': end_fit})
    add(body)
    add(box((44, -34, 34), (L, 34, 40), paintt))                                      # hood
    add(box((-L, -34, 34), (-56, 34, 40), paintt))                                    # trunk
    add(extrude_y([(-56, 34), (44, 34), (18, 62), (-40, 62)], -32, 32, 'car_window', ['car_window', 'car_window', paintt, 'car_window']))
    if lightbar:
        add(box((-12, -24, 62), (8, 24, 68), {'all': 'car_chrome', 'top': 'lightbar', 'x+': 'lightbar', 'x-': 'lightbar'}))
    add(box((L, -34, 14), (L + 4, 34, 22), 'car_chrome'))                             # bumpers
    add(box((-L - 4, -34, 14), (-L, 34, 22), 'car_chrome'))
    for wx in (56, -56):
        for y0, y1 in ((30, 40), (-40, -30)):
            # wheels are built in world space so the tire texture stays aligned when the car is turned
            if along_y:
                brushes.append(cylinder_x(cy + wx, cx - y1, cx - y0, 14 + z, 14, 8, 'TIRE_01', 'car_under'))
            else:
                brushes.append(cylinder_y(cx + wx, cy + y0, cy + y1, 14 + z, 0, 14, 8, 'TIRE_01', 'car_under'))
    # sc_car (game/dlls/svencraft/sc_car.cpp): smokes when hurt, burns, blows up and turns into its burnt copy
    # (a func_illusionary it takes the model of); spawnflag 1: burnt out already
    wreck = 'sc_wreck%d' % len(CARS)
    kv = {'classname': 'sc_car', 'zhlt_lightflags': '2', 'targetname': 'sc_car', 'wreck': wreck}
    if wrecked:
        kv['spawnflags'] = '1'
    ents.append(entity(kv, brushes))
    burnt = []
    for b in brushes:
        c = Brush()
        c.faces = [[f[0], BURNT.get(f[1], f[1])] + f[2:] for f in b.faces]
        burnt.append(c)
    ents.append(entity({'classname': 'func_illusionary', 'targetname': wreck, 'zhlt_lightflags': '2'}, burnt))


