# Xen leaks through it: Half-Life's Xen flora on the ground around it (the trees lash whoever comes close, the light
# plants pull in, the spores can be shot)
def rift_ground(x, y):
    """on realistic ground: outside the cells the rift removed"""
    cx, cy = (x + H) // G * G - H + G / 2, (y + H) // G * G - H + G / 2
    return math.hypot(cx - RIFT[0], cy - RIFT[1]) >= RIFT[2]


xrng, xen = random.Random(23), []
for cls, n, room in (('xen_tree', 3, 110), ('xen_plantlight', 5, 60), ('xen_spore_large', 1, 90), ('xen_spore_medium', 2, 60),
                     ('xen_spore_small', 3, 40), ('xen_hair', 6, 30)):
    k = 0
    while k < n:
        a, r = xrng.uniform(0, 2 * math.pi), RIFT[2] + xrng.uniform(60, 240)
        x, y = RIFT[0] + r * math.cos(a), RIFT[1] + r * math.sin(a)
        if (not rift_ground(x, y) or y < 380 or abs(x) > H - 300 or abs(y) > H - 300 or math.hypot(x - 900, y - 420) < 160
                or any(math.hypot(x - mx, y - my) < 100 for _, mx, my, _ in MONSTERS)
                or any(math.hypot(x - ox, y - oy) < room + oroom for ox, oy, oroom in xen)):
            continue
        xen.append((x, y, room))
        if cls != 'xen_hair':
            FURNITURE.append((x - room / 2, y - room / 2, x + room / 2, y + room / 2))   # no AI nodes in them
        ents.append(entity({'classname': cls, 'origin': '%d %d %d' % (x, y, surface_z(x, y) - 2), 'angles': '0 %d 0' % xrng.randint(0, 359)}))
        k += 1

