# ---------------------------------------------------------------- AI nodes: Half-Life monsters path between them
def node_blocked(x, y, pad):
    for x0, y0, x1, y1 in BUILDINGS:
        near = x0 - pad < x < x1 + pad and y0 - pad < y < y1 + pad
        inside = x0 + 16 + pad < x < x1 - 16 - pad and y0 + 16 + pad < y < y1 - 16 - pad
        if near and not inside:
            return True            # in a wall or right against one
    for fx0, fy0, fx1, fy1 in FURNITURE:
        if fx0 - pad / 2 < x < fx1 + pad / 2 and fy0 - pad / 2 < y < fy1 + pad / 2:
            return True
    for cx, cy, ay in CARS:
        hx, hy = (60, 112) if ay else (112, 60)
        if abs(x - cx) < hx + pad / 2 and abs(y - cy) < hy + pad / 2:
            return True
    if ground_z(x, y) < POND[4] + 8:
        return True            # in the pond: Half-Life's walkers don't swim
    return math.hypot(x - RIFT[0], y - RIFT[1]) < RIFT[2] + 48   # the rift's blocks only exist in the game


def node_z(x, y):
    for x0, y0, x1, y1 in BUILDINGS:
        if x0 < x < x1 and y0 < y < y1:
            return 8           # a building's floor slab
    return max(ground_z(x, y), 8)


NODE_STEP = 176
node_pts = [(gx, gy) for gx in range(-H + 176, H - 175, NODE_STEP) for gy in range(-H + 176, H - 175, NODE_STEP)]
for x0, y0, x1, y1 in BUILDINGS:                       # a few inside every building
    for fx in (0.3, 0.7):
        for fy in (0.3, 0.7):
            node_pts.append((int(x0 + (x1 - x0) * fx), int(y0 + (y1 - y0) * fy)))
for dx_, dy_, nx_, ny_ in DOORS:                       # and either side of each doorway
    node_pts += [(dx_ + nx_ * 56, dy_ + ny_ * 56), (dx_ - nx_ * 64, dy_ - ny_ * 64)]
nodes = 0
for x, y in node_pts:
    if node_blocked(x, y, 40) and not any(abs(x - d[0]) < 80 and abs(y - d[1]) < 80 for d in DOORS):
        continue
    ents.append(entity({'classname': 'info_node', 'origin': '%d %d %d' % (x, y, node_z(x, y) + 32)}))
    nodes += 1
print('AI nodes', nodes)

