# the light compiler doesn't know the diggable geometry: a copy of it casts the shadows on the map's brush
# entities (cars, doors, crates, glass) and is removed when the map starts (sc_world.cpp)
def plain(brush):
    c = Brush()
    c.faces = [[f[0], 'OUT_CONCRETE1', None, None, (0, 0), (1, 1)] for f in brush.faces]
    return c


